// 每个发布窗口跑一次：预算不够就自动冻结发布
const r = errorBudget({ slo: 0.999, requests: 100000, bad: 40 })
if (r.exhausted || r.burnRate > 2) {
  console.warn(`错误预算只剩 ${r.remaining}，冻结本窗口发布`)
}
// 日志入库前先补齐必填字段，缺 traceId 的直接打回
