// 估算小包服务的链路成本：
const wire = headerOverhead({ payload: 64, layers: ["eth", "ip", "tcp"] })
console.log(`64 字节心跳实际占 ${wire.total} 字节，效率 ${wire.efficiency}`)
// 估算首屏时间：
const cost = httpRequestCost({ version: "h2", requests: 30, rttMs: 40, keepAlive: true })
// 40ms RTT 下，h2 首屏只需 2 个往返 = 80ms；http1.1 串行要 31 个往返 = 1240ms

stages.code:
const HEADERS = { eth: 14, ip: 20, ipv6: 40, tcp: 20, udp: 8, tls: 5, quic: 0 }

function headerOverhead(req) {
  const payload = req.payload
  if (!(payload >= 0)) throw new Error('payload 必须是非负数')
  let overhead = 0
  for (const layer of req.layers || []) {
    const h = HEADERS[layer]
    if (h === undefined) throw new Error('未知协议层: ' + layer)
    overhead += h
  }
  const total = payload + overhead
  return {
    payload,
    overhead,
    total,
    // 有效载荷占比：payload / 总字节。0 字节时约定为 0，避免 0/0 出 NaN
    efficiency: total === 0 ? 0 : Math.round((payload / total) * 10000) / 10000
  }
}

