    same(congestionWindow({ rounds: 0 }), [1])
    same(congestionWindow({ rounds: 0, init: 10 }), [10])
  })
  check('丢包减半不低于 2，避免窗口塌到 1', () => {
    same(congestionWindow({ rounds: 1, ssthresh: 2, lossRound: 1 }), [1, 2])
