  const rttvar = req.rttvarMs
  const minRto = req.minRto === undefined ? 200 : req.minRto
  // RFC 6298：RTO = SRTT + 4 × RTTVAR，并夹在 [minRto, 60s]
  const rto = srtt + 4 * rttvar
  return Math.max(minRto, Math.round(rto))
