    return { clientQueries: 1, resolverQueries: 3, totalRtt: 4 }
  }
  if (r.mode === 'iterative') {
    // 客户端自己依次问本地、根、TLD、权威
    return { clientQueries: 4, resolverQueries: 0, totalRtt: 4 }
  }
  throw new Error('未知查询模式: ' + r.mode)
